import{c as a,S as e,j as r,m as l}from"./chunks/framework.8aa1YH_s.js";const y=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 2: Türk Yazı Dilinin Tarihî Gelişimi ve Kolları","description":"","frontmatter":{},"headers":[],"relativePath":"2 Türk Yazı Dilinin Tarihî Gelişimi ve Kolları.md","filePath":"2 Türk Yazı Dilinin Tarihî Gelişimi ve Kolları.md"}'),n={name:"2 Türk Yazı Dilinin Tarihî Gelişimi ve Kolları.md"};function k(t,i,d,s,u,o){return e(),r("div",null,[...i[0]||(i[0]=[l('<h1 id="turk-dil-bilgisi-serisi-2-turk-yazı-dilinin-tarihi-gelisimi-ve-kolları" tabindex="-1">Türk Dil Bilgisi Serisi - 2: Türk Yazı Dilinin Tarihî Gelişimi ve Kolları <a class="header-anchor" href="#turk-dil-bilgisi-serisi-2-turk-yazı-dilinin-tarihi-gelisimi-ve-kolları" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 2: Türk Yazı Dilinin Tarihî Gelişimi ve Kolları”">​</a></h1><p>İlk bölümümüzde dilin tanımını yapmış ve Türkçenin dünya dilleri arasındaki yerini (eklemeli bir dil ve Altay ailesinden olduğunu) incelemiştik. Bu yazımızda, Prof. Dr. Muharrem Ergin&#39;in sistematiğiyle Türk yazı dilinin tarih sahnesine çıkışını, geçirdiği evreleri ve coğrafi hareketlerle nasıl kollara ayrıldığını ele alıyoruz.</p><hr><h2 id="_1-giris-yazı-dili-ve-tarihi-surec" tabindex="-1">1. Giriş: Yazı Dili ve Tarihî Süreç <a class="header-anchor" href="#_1-giris-yazı-dili-ve-tarihi-surec" aria-label="Permalink to “1. Giriş: Yazı Dili ve Tarihî Süreç”">​</a></h2><p>Bir dilin asıl gücü ve medeniyet kurma kapasitesi, onun bir &quot;yazı dili&quot; haline gelmesiyle ölçülür. Türkçenin belgelenebilen, takip edilebilen ilk metinlerinden günümüze kadar geçen sürede geçirdiği aşamalar, Türk milletinin tarihi ve coğrafi yolculuğu ile doğrudan paralellik gösterir.</p><p>Muharrem Ergin&#39;e göre Türk yazı dili tarihi genel olarak iki büyük döneme ayrılır:</p><ol><li><strong>Ortak Dönem (Eski Türkçe)</strong></li><li><strong>Kollara Ayrılma Dönemi (Kuzey-Doğu ve Batı Türkçesi)</strong></li></ol><hr><h2 id="_2-eski-turkce-donemi-musterek-yazı-dili" tabindex="-1">2. Eski Türkçe Dönemi (Müşterek Yazı Dili) <a class="header-anchor" href="#_2-eski-turkce-donemi-musterek-yazı-dili" aria-label="Permalink to “2. Eski Türkçe Dönemi (Müşterek Yazı Dili)”">​</a></h2><p>Türkçenin metinlerle takip edilebilen <strong>en eski, en karanlık ve aynı zamanda en saf</strong> dönemidir. Bu dönemin en büyük özelliği, bütün Türk boylarının tek bir merkezde, tek bir ortak yazı dili etrafında toplanmış olmasıdır. Yani o devirde henüz şiveler ve kollar ayrışmamıştı; nerede bir Türk varsa aynı yazı dilini kullanıyordu.</p><ul><li><strong>Zaman Aralığı:</strong> Başlangıcından 10-11. yüzyıllara kadar olan dönemi kapsar.</li><li><strong>En Önemli Eserler:</strong> Orhun (Göktürk) Abideleri bu dönemin ve Türk yazı dilinin ilk şaheseridir. Ardından gelen Uygur dönemi metinleri (Altun Yaruk, Irk Bitig vb.) de bu döneme dahildir.</li><li><strong>Karakteri:</strong> Yabancı dillerin etkisinden uzak, Türkçenin kendi yapısını ve mantığını en çıplak haliyle gösteren dönemdir.</li></ul><hr><h2 id="_3-buyuk-ayrım-kuzey-dogu-turkcesi-ve-batı-turkcesi" tabindex="-1">3. Büyük Ayrım: Kuzey-Doğu Türkçesi ve Batı Türkçesi <a class="header-anchor" href="#_3-buyuk-ayrım-kuzey-dogu-turkcesi-ve-batı-turkcesi" aria-label="Permalink to “3. Büyük Ayrım: Kuzey-Doğu Türkçesi ve Batı Türkçesi”">​</a></h2><ol start="11"><li>yüzyıldan itibaren Türk boylarının Asya&#39;nın dört bir yanına, özellikle de Hazar Denizi&#39;nin güneyinden Anadolu&#39;ya ve Avrupa&#39;ya doğru büyük göçleri başladı. Bu coğrafi ayrılık, doğal olarak yazı dilinin de kollara ayrılmasına neden oldu. Ortak Eski Türkçe dönemi kapandı ve Türk dili iki ana kola bölündü:</li></ol><p>[ ESKİ TÜRKÇE ] | +--------------+--------------+ | | [ KUZEY-DOĞU TÜRKÇESİ ] [ BATI TÜRKÇESİ ] | | +-------+-------+ +-------+-------+ | | | | | [Kuzey T.] [Doğu T.] [E.A.T] [Osm.] [T.T] (Kıpçak) (Çağatay)</p><h3 id="a-kuzey-dogu-turkcesi" tabindex="-1">A) Kuzey-Doğu Türkçesi <a class="header-anchor" href="#a-kuzey-dogu-turkcesi" aria-label="Permalink to “A) Kuzey-Doğu Türkçesi”">​</a></h3><p>Orta Asya&#39;da kalan ve kuzeye (Sibirya/Karadeniz&#39;in kuzeyi) doğru yayılan Türklerin kullandığı yazı dilidir. Zamanla kendi içinde iki alt kola ayrılmıştır:</p><ol><li><strong>Doğu Türkçesi (Çağatayca):</strong> Karluk ve Uygur boylarının devamı niteliğindedir. Ali Şîr Nevâî gibi büyük sanatçılarla altın çağını yaşamıştır. Günümüzdeki Özbekçe ve Uygurca bu koldan gelir.</li><li><strong>Kuzey Türkçesi (Kıpçakça):</strong> Hazar&#39;ın kuzeyi ve Karadeniz civarında gelişmiştir. Günümüzdeki Kazakça, Kırgızca ve Tatarca gibi diller bu kolun devamıdır.</li></ol><h3 id="b-batı-turkcesi-oguz-turkcesi" tabindex="-1">B) Batı Türkçesi (Oğuz Türkçesi) <a class="header-anchor" href="#b-batı-turkcesi-oguz-turkcesi" aria-label="Permalink to “B) Batı Türkçesi (Oğuz Türkçesi)”">​</a></h3><p>Hazar Denizi’nin güneyinden geçerek İran, Irak, Suriye, Anadolu ve Balkanlar&#39;a yayılan <strong>Oğuz Türklerinin</strong> meydana getirdiği yazı dilidir. Bugün bizim de konuştuğumuz dil olan Türkiye Türkçesi, Batı Türkçesinin doğrudan bir devamıdır.</p><hr><h2 id="_4-batı-turkcesinin-tarihi-evreleri" tabindex="-1">4. Batı Türkçesinin Tarihî Evreleri <a class="header-anchor" href="#_4-batı-turkcesinin-tarihi-evreleri" aria-label="Permalink to “4. Batı Türkçesinin Tarihî Evreleri”">​</a></h2><p>Bizim için hayati öneme sahip olan Batı Türkçesi, kendi içinde kesintisiz bir zincir halinde üç büyük döneme ayrılır:</p><h3 id="_1-eski-anadolu-turkcesi-13-15-yuzyıl" tabindex="-1">1. Eski Anadolu Türkçesi (13. - 15. Yüzyıl) <a class="header-anchor" href="#_1-eski-anadolu-turkcesi-13-15-yuzyıl" aria-label="Permalink to “1. Eski Anadolu Türkçesi (13. - 15. Yüzyıl)”">​</a></h3><ul><li>Batı Türkçesinin ilk dönemidir.</li><li>Anadolu Selçukluları, Beylikler dönemi ve Osmanlı Devleti&#39;nin kuruluş aşamasını kapsar.</li><li><strong>Yunus Emre</strong>, <strong>Aşık Paşa</strong> gibi isimlerin eserleri bu dönemin en güzel örnekleridir.</li><li>Eski Türkçenin izlerini taşımakla birlikte, dilde sadelik ve Oğuzca unsurlar ön plandadır.</li></ul><h3 id="_2-osmanlıca-osmanlı-turkcesi-16-20-yuzyıl-basları" tabindex="-1">2. Osmanlıca / Osmanlı Türkçesi (16. - 20. Yüzyıl Başları) <a class="header-anchor" href="#_2-osmanlıca-osmanlı-turkcesi-16-20-yuzyıl-basları" aria-label="Permalink to “2. Osmanlıca / Osmanlı Türkçesi (16. - 20. Yüzyıl Başları)”">​</a></h3><ul><li>Osmanlı İmparatorluğu&#39;nun büyümesiyle paralel olarak gelişen klasik dönemdir.</li><li><strong>En belirgin özelliği:</strong> Devletin bir imparatorluk haline gelmesiyle birlikte yazı diline yoğun biçimde Arapça ve Farsça kelimelerin, kuralların ve terkiplerin (tamlamaların) girmiş olmasıdır.</li><li>Aydınların ve sarayın dili (yazı dili) oldukça ağırlaşmış, ancak halkın konuştuğu dil kendi doğallığını korumuştur.</li></ul><h3 id="_3-turkiye-turkcesi-20-yuzyıl-gunumuz" tabindex="-1">3. Türkiye Türkçesi (20. Yüzyıl - Günümüz) <a class="header-anchor" href="#_3-turkiye-turkcesi-20-yuzyıl-gunumuz" aria-label="Permalink to “3. Türkiye Türkçesi (20. Yüzyıl - Günümüz)”">​</a></h3><ul><li>Batı Türkçesinin üçüncü ve içinde bulunduğumuz modern dönemidir.</li><li>1911 yılında Ömer Seyfettin, Ali Canip Yöntem ve Ziya Gökalp&#39;in Selanik&#39;te başlattığı <strong>&quot;Genç Kalemler - Yeni Lisan&quot;</strong> hareketi bu dönemin miladıdır.</li><li>Yazı dilindeki yabancı dil bilgisi kuralları atılmış, dil sadeleştirilmiş ve <strong>İstanbul Türkçesi</strong> ortak yazı dili olarak kabul edilmiştir. bugün Türkiye Cumhuriyeti&#39;nde ve KKTC&#39;de konuşulan, yazdığımız modern dildir.</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Türk yazı dili, tek bir kökten (Eski Türkçe) beslenerek coğrafyanın genişlemesiyle büyük kollara ayrılmış muazzam bir çınardır. Bizim bugün kullandığımız dil, bu çınarın <strong>Batı Türkçesi (Oğuzca)</strong> kolunun en olgun meyvesi olan <strong>Türkiye Türkçesi</strong>dir.</p><p>Serimizin 3. bölümünde, dilin en küçük yapı taşına iniyoruz ve <strong>&quot;Ses Bilgisi (Fonetik) - Türkçedeki Sesler ve Vokaller (Ünlüler)&quot;</strong> konusunu, ünlü uyumlarının mantığını ele alacağız. Okumaya devam edin!</p>',33)])])}const z=a(n,[["render",k]]);export{y as __pageData,z as default};
